) bool {
	if len(sc.Connects) != 2 {
		return false
	}

	storey0, ok0 := storeyIndex[sc.Connects[0]]
	storey1, ok1 := storeyIndex[sc.Connects[1]]
	if !ok0 || !ok1 {
